-- Live schema migration: add region column to analytics.events
-- This uses ALTER TABLE which is non-blocking in ClickHouse (no downtime).

ALTER TABLE analytics.events ADD COLUMN IF NOT EXISTS region String DEFAULT 'unknown';

-- Backfill region based on user_id prefix
ALTER TABLE analytics.events UPDATE region = 'us-east' WHERE startsWith(user_id, 'u1');
ALTER TABLE analytics.events UPDATE region = 'eu-west' WHERE startsWith(user_id, 'u2');
ALTER TABLE analytics.events UPDATE region = 'unknown' WHERE NOT startsWith(user_id, 'u1') AND NOT startsWith(user_id, 'u2');
